const cfg = $('CONFIG - thèmes et chaîne').first().json;

const historique =
  $('REGROUPER HISTORIQUE').first().json.historique || [];

// Retraitement explicite uniquement avant validation ou création d'un brouillon.
const retryRows=historique.filter(r=>String(r.statut||'').trim().toUpperCase()==='A_RETRAITER' &&
 !String(r.draft_id||'').trim() && String(r.validation_contact||'').trim().toUpperCase()!=='OUI' &&
 !String(r.email_contact||'').trim());
const retry=new Set(retryRows.map(r=>String(r.cle_unique||'').trim()));
// Livres déjà enregistrés : ne pas les traiter deux fois.
const existants = new Set(
  historique
    .filter(r=>!retry.has(String(r.cle_unique||'').trim()))
    .map(r => String(r.cle_unique || '').trim())
    .filter(Boolean)
);

// Auteurs à ne pas contacter.
const banned = new Set(
  historique
    .filter(r =>
      ['NE_PAS_CONTACTER', 'REFUSE', 'OPPOSITION', 'BLOQUE_ELIGIBILITE'].includes(
        String(r.statut || '').trim().toUpperCase()
      )
    )
    .map(r => String(r.auteur || '').trim().toLowerCase())
);

// Réutiliser les données enregistrées sans dépendre du classement Google Books.
if(retryRows.length){
 const seen=new Set();
 const records=retryRows.filter(r=>{
  const key=String(r.cle_unique||'').trim();
  const author=String(r.auteur||'').trim();
  if(!key || !author || !String(r.livre||'').trim() || seen.has(key) || banned.has(author.toLowerCase()))return false;
  seen.add(key);return true;
 }).slice(0,20).map(r=>({json:{
  cle_unique:String(r.cle_unique).trim(),auteur:String(r.auteur).trim(),livre:String(r.livre).trim(),
  editeur:String(r.editeur||''),date_publication:String(r.date_publication||''),
  description_livre:String(r.description_livre||'').slice(0,1600),source_livre:String(r.source_livre||''),
  sous_titre:String(r.sous_titre||''),langue:String(r.langue||'à vérifier à partir du titre et de la description'),categories:[],
  chaine:String(r.chaine||cfg.chaine),statut:'A_VERIFIER',validation_contact:'NON'
 },pairedItem:{item:0}}));
 if(!records.length)throw new Error('Les fiches A_RETRAITER sont incomplètes ou leur auteur reste bloqué dans une autre ligne. Vérifiez ces fiches sans supprimer les oppositions.');
 return records;
}

const livres = $input.all().flatMap((page,pageIndex)=> {
 if(page.json.error) throw new Error('Google Books a renvoyé une erreur : vérifier le nœud HTTP.');
 return (page.json.items || []).map(b=>({b,pageIndex}));
});
// Priorité aux fiches renseignées ; les autres passent ensuite en recherche.
livres.sort((a,b)=>Number(retry.has(b.b.id))-Number(retry.has(a.b.id)) || Number(Boolean(b.b.volumeInfo?.publisher))-Number(Boolean(a.b.volumeInfo?.publisher)));

const candidats = [];
const norm=s=>String(s||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
const institution=/\b(library|bibliotheque|association|society|societe|congress|congres|committee|comite|university|universite|institute|institut|ministere|department|collectif|anonymous|anonyme)\b/;
const catalogue=/^(revue|bulletin|almanach|catalogue|bibliographie|bibliography|finding lists|ibss)\b/;
const vus = new Set();

// Présélection plafonnée à 20 ; le tri éditorial retient ensuite max_livres.
const max = 20;

for (const {b,pageIndex} of livres) {
  if(retry.size && !retry.has(b.id))continue;
  const v = b.volumeInfo || {};

  const cle = String(b.id || '').trim();
  const auteur = String((v.authors || [])[0] || '').trim();
  const livre = String(v.title || '').trim();
  const editeur = String(v.publisher || '').trim();

  // Préfiltre conservateur : métadonnées françaises et auteur individuel.
  if(String(v.language||'').toLowerCase()!=='fr' || institution.test(norm(auteur)) || catalogue.test(norm(livre))) continue;
  // On conserve la date à titre informatif, sans filtrer dessus.
  const date = String(v.publishedDate || '').trim();

  // Écarter uniquement les fiches incomplètes, doublons
  // et auteurs à ne pas contacter.
  if (
    !cle ||
    !auteur ||
    !livre ||
    existants.has(cle) ||
    vus.has(cle) ||
    banned.has(auteur.toLowerCase())
  ) {
    continue;
  }

  vus.add(cle);

  candidats.push({
    json: {
      cle_unique: cle,
      auteur: auteur,
      livre: livre,
      sous_titre: String(v.subtitle||''),
      langue: String(v.language||''),
      categories: v.categories||[],
      editeur: editeur,
      date_publication: date,
      description_livre: String(v.description || '')
        .replace(/<[^>]*>/g, ' ')
        .slice(0, 1600),
      source_livre: String(
        v.infoLink || 'https://books.google.com/'
      ),
      chaine: cfg.chaine,
      statut: 'A_VERIFIER',
      validation_contact: 'NON'
    },
    pairedItem: {
      item: pageIndex
    }
  });

  if (candidats.length >= max) {
    break;
  }
}

if (!candidats.length) throw new Error('Aucun nouveau livre exploitable dans les 5 pages : résultats déjà enregistrés, langue non française ou inconnue, institutions, catalogues ou fiches incomplètes. Modifiez la recherche dans CONFIG ; conservez votre historique.');
return candidats;

const recherches = $input.all();

return recherches.map((item, i) => {

  // Retrouver le livre associé à cette recherche Brave.
  const livre = $('VALIDER SELECTION EDITORIALE').itemMatching(i).json;

  // Extraire au maximum 5 résultats de recherche.
  const web = item.json.web?.results || [];

  const resultats = web.slice(0, 10).map(r => ({
    titre: r.title || '',
    url: r.url || '',
    description: r.description || ''
  }));

  // Conserver les informations du bon livre.
  return {
    json: {
      ...livre,
      resultats_auteur: resultats
    },
    pairedItem: {
      item: i
    }
  };

});

function signalDeces(value) {
 const s=String(value||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase()
  // Neutraliser seulement les mentions explicitement négatives, pas les autres indices.
  .replace(/\baucune mention de deces(?:\s+relevee)?\b/g, '')
  .replace(/\baucun (?:signe|signal|indice) de deces\b/g, '')
  .replace(/\babsence de mention de deces\b/g, '')
  .replace(/\bpas de mention de deces\b/g, '');
 // Des dates seules peuvent décrire des études, un mandat ou le sujet du livre.
 // Les mentions explicites restent des signaux à examiner, jamais une preuve.
 return /\b(decede(?:e|s|es)?|deces|mort(?:e|s|es)?|died|deceased|obituary)\b/.test(s);
}
const recherches = $input.all();

return recherches.map((item, i) => {

  // Retrouver le dossier associé à cette recherche éditeur.
  const livre = $('ENRICHIR PISTES AUTEUR')
    .itemMatching(i).json;

  // Résultats de la recherche de l'éditeur.
  const web = item.json.web?.results || [];

  const resultats_editeur = web.slice(0, 20).map(r => ({
    titre: r.title || '',
    url: r.url || '',
    description: r.description || ''
  }));

  // Réunir les pistes auteur et éditeur.
  const sources = [
    ...(livre.resultats_auteur || []),
    ...resultats_editeur
  ];

  // Extraire les e-mails présents dans les extraits Brave.
  // Attention : ces adresses ne sont PAS vérifiées.
  const emails = [];
  const vus = new Set();

  const norm=s=>String(s||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,' ').trim();
  const auteurNorm=norm(livre.auteur);
  const editeurNorm=norm(livre.editeur).replace(/\b(editions?|publishing|publishers?|press|books)\b/g,' ').replace(/\s+/g,' ').trim();
  for (const r of sources) {
    const contexte=norm(r.titre+' '+r.description+' '+r.url);
    // Une présence nominale est seulement un indice, jamais une validation.
    if(!((auteurNorm.length>5 && contexte.includes(auteurNorm)) || (editeurNorm.length>3 && contexte.includes(editeurNorm))))continue;
    if(!/^https:\/\//i.test(String(r.url||'')))continue;

    const description = String(r.description || '');
    const url = String(r.url || '');

    const texteContact = description.replace(/<[^>]*>/g,'')
      .replace(/&#64;|&#x40;|&commat;/gi,'@')
      .replace(/\s*\[(?:at|arobase)\]\s*|\s*\((?:at|arobase)\)\s*/gi,'@')
      .replace(/\s*\[(?:dot|point)\]\s*/gi,'.');
    const correspondances = texteContact.matchAll(
      /[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/gi
    );

    for (const m of correspondances) {

      const email = m[0].toLowerCase();
      if(/^(orders?|support|customer|international_cs|noreply|no-reply|sales|info\.presse)@/i.test(email))continue;
      const cle = email + '|' + url;

      if (vus.has(cle)) continue;

      vus.add(cle);

      emails.push({
        email: email,
        source: url,
        extrait: description,
        verification: 'NON'
      });
    }
  }

  // Conserver uniquement les URL HTTPS et retirer les doublons.
  const urls_candidats = [
    ...new Set(
      sources
        .map(r => String(r.url || ''))
        .filter(url => /^https:\/\//i.test(url))
    )
  ].slice(0, 40);

  return {
    json: {

      // Un signal est un motif de revue, jamais une preuve de décès.
      signal_deces: sources.some(r=>signalDeces(r.titre+' '+r.description)) || signalDeces(livre.description_livre),
      // Informations du livre et pistes de l'auteur.
      ...livre,

      // Pistes de l'éditeur.
      resultats_editeur: resultats_editeur,

      // Données structurées pour les étapes suivantes.
      candidats_email: emails,
      urls_candidats: urls_candidats,

      // Champs destinés à Google Sheets.
      recherches_auteur: JSON.stringify(
        livre.resultats_auteur || []
      ),

      recherches_editeur: JSON.stringify(
        resultats_editeur
      ),

      emails_candidats: JSON.stringify(
        emails
      ),

      sources_contacts: JSON.stringify(
        urls_candidats
      ),

      // Aucun contact n'est validé automatiquement.
      source_contact_validee: '',
      email_contact: '',
      type_contact: '',
      validation_contact: 'NON',
      statut: 'A_VERIFIER',
      draft_id: ''

    },

    pairedItem: {
      item: i
    }
  };

});

