   texte=texte.replace(/Pourriez-vous me confirmer que Mathias Bernard est toujours l'auteur de référence et transmettre ma demande \?/g, 'Pourriez-vous lui transmettre cette invitation ?');
   if(/\bj['’]ai (?:lu|relu|dévoré)|\baprès (?:avoir lu|lecture de)|\bayant lu\b/i.test(texte)) {
