   }
   // Corrections déterministes limitées aux formulations observées.
   texte=texte.replace(/\bUn échange ([^.!?\n]+?) nous intéresserait vivement\./g, 'Je serais vivement intéressé par un échange $1.');
   texte=texte.replace(/\bnous indiquer\b/gi, 'm’indiquer');
   texte=texte.replace(/\bde nos cadres constitutionnels\b/gi, 'des cadres constitutionnels français');
   texte=texte.replace(/\bnos cadres constitutionnels\b/gi, 'les cadres constitutionnels français');
   if(/https?:\/\//i.test(texte)){
    erreur=true;alertes.push('BLOCAGE_TEXTE : lien non autorisé dans '+cle);
   }
   // Un choix de style nécessite une relecture, pas la suppression du texte.
   const style=texte.match(/assistant éditorial|équipe éditoriale|\bnous\b|\bnotre\s+(?:chaîne|chaine|équipe|equipe|média|media|plateforme)\b|\bnos\s+(?:émissions|emissions|vidéos|videos)\b/gi);
   if(style)alertes.push('STYLE_A_RELIRE : '+cle+' contient '+[...new Set(style)].join(', ')+'. Vérifier le contexte et privilégier une rédaction au nom de Walid.');
   // Retirer uniquement une clôture terminale éventuellement produite malgré le prompt.
   texte=texte.replace(/\n+(?:Cordialement|Bien cordialement|Bien à vous|Avec mes salutations)[\s\S]*$/i,'').trim();
   texte=texte.replace(/\n+(?:Walid\s*\n+)?Impacteur (?:Afrique|Frexit)\s*$/i,'').trim();
   sortie[cle]=texte+'\n\n'+FOOTER+'\n\nCordialement,\nWalid\n'+base.chaine;
  } else sortie[cle]=texte;
 }
 if(!['Impacteur Afrique','Impacteur Frexit'].includes(base.chaine)){erreur=true;alertes.push('BLOCAGE_CHAINE : chaîne inconnue.');}
 if(bloque||erreur) for(const cle of champs)sortie[cle]='';
 alertes.push('CONTROLE_V6 : contrôle automatique effectué, validation humaine de l’identité, des faits, du texte et du contact requise.');
 return {json:{
  cle_unique:base.cle_unique,auteur:base.auteur,livre:base.livre,editeur:base.editeur,
