const reponse=$input.first().json;
if(reponse.stop_reason==='max_tokens')throw new Error('Tri éditorial : réponse tronquée par la limite de sortie. Aucun candidat validé.');
const base=$('PREPARER SELECTION EDITORIALE').first().json.candidats;
const txt=($input.first().json.content||[]).map(x=>x.text||'').join('\n').trim().replace(/^```(?:json)?\s*/i,'').replace(/\s*```$/,'');
let parsed;try{parsed=JSON.parse(txt);}catch(e){throw new Error('Tri éditorial : JSON incomplet ou invalide. Aucune recherche de contact lancée. Consulter la réponse complète du nœud Claude.');}
if(!Array.isArray(parsed.evaluations))throw new Error('Tri éditorial : évaluations absentes.');
const map=new Map(base.map(x=>[x.cle_unique,x])),seen=new Set();
const out=[];const max=Math.max(1,Math.min(5,Number($('CONFIG - thèmes et chaîne').first().json.max_livres)||3));
for(const e of parsed.evaluations){
